<script setup lang="ts">
import {computed,reactive,ref,nextTick,watch} from 'vue';
import type {ViewModel} from '../app/useWorkspace';
import {usePersonalTerminal} from '../app/usePersonalTerminal';
import CharacterAvatar from './CharacterAvatar.vue';
import CharacterImageEditor from './CharacterImageEditor.vue';
import {majorCharacter} from '../domain/characterImages';
import SaveStatus from './SaveStatus.vue';
import AutoTextarea from './AutoTextarea.vue';
import {targetActors,groupOwner,groupMemberIds} from '../domain/personalTerminal';
import {messagePage,terminalMessageVisible} from '../domain/terminalLedger';
import TerminalIcon from './TerminalIcon.vue';
const props=defineProps<{w:ViewModel}>();defineEmits<{close:[];'drag-start':[event:PointerEvent];'drag-move':[event:PointerEvent];'drag-end':[]}>();
const u=reactive(usePersonalTerminal(props.w));
const feed=ref<HTMLElement>();
const imageCharacter=ref(''),showImageCharacters=ref(false);
const majorCharacters=computed(()=>(props.w.localService?.majorCharacters||props.w.localService?.characters||[]).filter(a=>majorCharacter(a.name)));
const titles:Record<string,string>={home:'个人终端',messages:'通讯',chat:'通讯',friends:'好友',add:'添加好友',profile:'好友资料','new-group':'发起群聊','invite-room':'邀请游戏好友','invite-group':'邀请好友','group-info':'群资料',courses:'课程表',course:'课程详情',apps:'应用',games:'游戏室','new-room':'创建房间',room:'国王游戏',king:'国王游戏',history:'游戏记录',account:'我的',legacy:'剧情群聊'};
const currentTitle=computed(()=>u.page==='chat'?u.conversation?.title||'通讯':titles[u.page]||'个人终端');
const filteredFriends=computed(()=>u.friends.filter(f=>(u.name(f.id)+f.note).includes(u.search)));
const searchedMessages=computed(()=>u.messages.filter(m=>!searchMessages.value||m.text.includes(chatSearch.value)));
const pagedMessages=computed(()=>messagePage(searchedMessages.value,u.historyPage));
const mineWaiting=computed(()=>u.round?.phase==='respond'&&targetActors(u.round).includes('player')&&!u.round.replies.some(r=>r.id==='player'));
const npcWaiting=computed(()=>u.round?.phase==='respond'&&targetActors(u.round).some(id=>id!=='player'&&!u.round!.replies.some(r=>r.id===id)));
const chatSearch=ref(''),searchMessages=ref(false);
watch(chatSearch,()=>u.historyPage=0);
const conversations=computed(()=>u.visibleConversations.filter(c=>c.joined!==false&&c.title.includes(u.search)&&(u.conversationFilter==='all'||(u.conversationFilter==='group'?c.group:!c.group))));
const messageTime=(at:string)=>/^\d{1,2}:\d{2}$/.test(at)?at:/^\d{4}-/.test(at)?new Date(at).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}):'';
const members=computed(()=>u.conversation?groupMemberIds(u.conversation):[]);
const groupRole=(id:string)=>u.conversation&&groupOwner(u.conversation)===id?'群主':u.conversation?.adminIds?.includes(id)?'管理员':'成员';
function member(id:string){if(id==='player'){u.go('account');return;}if(u.friends.some(f=>f.id===id))profile(id);else{u.go('add');}}
const shownCourses=computed(()=>u.t.courses.filter(c=>u.week||!u.storyClock.day||c.day===u.storyClock.day).sort((a,b)=>a.day-b.day||a.time.localeCompare(b.time)));
const nextCourse=computed(()=>shownCourses.value.find(c=>!u.storyClock.day||c.day>u.storyClock.day||c.time>u.storyClock.time));
const nav=computed(()=>['messages','chat','group-info','new-group','invite-group','legacy'].includes(u.page)?'messages':['friends','add','profile'].includes(u.page)?'friends':u.page==='home'?'home':['account','apps'].includes(u.page)?'account':'');
function profile(id:string){u.friendId=id;u.note=u.t.friends.find(f=>f.id===id)?.note||'';u.go('profile');}
function startRoom(){u.title='';u.picked=[];u.go('new-room');}
function groupInfo(){u.title=u.conversation?.title||'';u.note=u.conversation?.announcement||'';u.go('group-info');}
function back(){const destination:Record<string,string>={chat:'messages',profile:'friends',add:'friends','new-group':'messages','group-info':'chat','invite-room':'room','invite-group':'group-info',course:'courses',courses:'home',games:'home','new-room':'games',room:'games',king:'room',history:'king',account:'home',legacy:'messages'};u.go(destination[u.page]||'home');}
async function avatarChange(e:Event){const input=e.target as HTMLInputElement,file=input.files?.[0];if(file)await u.uploadAvatar(file);input.value='';}
watch(()=>[u.conversation?.messages.length,u.page],async()=>{await nextTick();if(feed.value)feed.value.scrollTop=feed.value.scrollHeight;});
const weekNames=['周一','周二','周三','周四','周五','周六','周日'];
</script>
<template>
<section class="pt" aria-label="个人终端"><div v-if="imageCharacter" class="pt-image-dialog" role="dialog" aria-modal="true" aria-label="编辑角色头像" @keydown.esc="imageCharacter=''"><button type="button" class="pt-image-close" aria-label="关闭头像编辑" autofocus @click="imageCharacter=''">关闭 ×</button><CharacterImageEditor :key="imageCharacter" :w="w" :id="imageCharacter"/></div>
 <header class="pt-header" title="拖动顶栏移动终端" @pointerdown="$emit('drag-start',$event)" @pointermove="$emit('drag-move',$event)" @pointerup="$emit('drag-end')" @pointercancel="$emit('drag-end')" @lostpointercapture="$emit('drag-end')"><button type="button" :aria-label="u.page==='home'?'返回桌面':'返回上一页'" @click="back">‹</button><div><strong>{{currentTitle}}</strong><small>STELLAR OS</small></div><span>{{u.clock.time}}</span><button type="button" aria-label="关闭个人终端" @click="$emit('close')">×</button></header>
 <div class="pt-save-status"><SaveStatus :status="w.storageStatus" :saved-at="w.lastSaved" :error="w.storageError"/><button type="button" :disabled="w.storageStatus==='saving'" @click="w.save()">立即保存</button></div>
 <div v-if="u.working" class="pt-progress" role="status">正在等待角色回应… <button type="button" disabled>请稍候</button></div>
 <div v-if="u.error" class="pt-error" role="alert">{{u.error}}<button type="button" aria-label="收起终端提示" @click="u.error=''">×</button></div>
 <main class="pt-screen" :class="{'pt-home-screen':u.page==='home'}" :aria-busy="u.working">
  <template v-if="u.page==='home'">
   <div class="pt-clock"><small>PERSONAL TERMINAL</small><b>{{u.clock.time}}</b><span>{{u.clock.label}}</span><small v-if="u.storyClock.location">{{u.storyClock.location}}</small><button class="pt-own" type="button" aria-label="设置终端头像" @click="u.go('account')"><img v-if="u.t.avatar" :src="u.t.avatar" :style="u.avatarStyle" alt="我的终端头像"><TerminalIcon v-else name="user"/></button></div>
   <button class="pt-card pt-notification" type="button" @click="u.go('messages')"><TerminalIcon name="chat"/><div><strong>未读消息 <em v-if="u.unread">{{u.unread}}</em></strong><p>{{u.visibleConversations.find(c=>c.unread)?.messages.at(-1)?.text||'暂时没有新消息'}}</p></div><span>›</span></button>
   <div class="pt-launch-grid"><button v-for="app in [{id:'messages',icon:'chat',name:'通讯',hint:'私聊与群聊'},{id:'friends',icon:'friends',name:'好友',hint:'好友列表 · 添加好友'},{id:'courses',icon:'calendar',name:'课程表',hint:'课程 · 授课安排'},{id:'games',icon:'crown',name:'游戏室',hint:'国王游戏'}]" :key="app.id" type="button" class="pt-app" :class="{gold:app.id==='games'}" @click="u.go(app.id)"><TerminalIcon :name="app.icon"/><strong>{{app.name}}<em v-if="app.id==='friends'&&u.incoming.length"> {{u.incoming.length}}</em></strong><small>{{app.hint}}</small></button></div>
   <button class="pt-card pt-next" type="button" @click="u.go('courses')"><TerminalIcon name="calendar"/><div><small>下一节课</small><strong>{{nextCourse?.title||'暂无已知课程'}}</strong><p>{{nextCourse?`${nextCourse.time} · ${nextCourse.place}`:'打开课程表，读取剧情中的安排'}}</p></div><span>›</span></button>
  </template>
  <template v-else-if="u.page==='messages'">
   <div class="pt-toolbar"><h2>通讯</h2><div class="pt-plus-wrap"><button type="button" aria-label="通讯操作" :aria-expanded="u.plusOpen" @click="u.plusOpen=!u.plusOpen">＋</button><div v-if="u.plusOpen" class="pt-plus-menu"><button type="button" @click="u.go('add')">添加好友</button><button type="button" @click="u.picked=[];u.title='';u.go('new-group')">发起群聊</button></div></div></div>
   <input v-model="u.search" aria-label="搜索会话" placeholder="搜索会话"><div class="pt-tabs"><button v-for="filter in [{id:'all',name:'全部'},{id:'private',name:'私聊'},{id:'group',name:'群聊'}] as const" :key="filter.id" type="button" :class="{active:u.conversationFilter===filter.id}" @click="u.conversationFilter=filter.id">{{filter.name}}</button></div>
   <p v-if="!u.visibleConversations.length" class="pt-empty">还没有会话<br>从好友资料发起私聊，或创建群聊。</p>
   <button v-for="c in conversations" :key="c.id" class="pt-row" type="button" @click="u.openConversation(c.id)"><span class="pt-avatar"><CharacterAvatar :w="w" :id="c.members[0]||''" :group="c.group"/></span><div><strong>{{c.title}}</strong><small>{{c.messages.filter(m=>!w.active||terminalMessageVisible(w.active,m)).at(-1)?.text||'暂无消息'}}</small><small v-if="c.origin==='story'">剧情群聊</small></div><time>{{messageTime(c.messages.filter(m=>!w.active||terminalMessageVisible(w.active,m)).at(-1)?.at||'')}}</time><em v-if="c.unread">{{c.unread}}</em><span>›</span></button>
  </template>
  <template v-else-if="u.page==='chat'&&u.conversation">
   <div class="pt-chat-identity"><span class="pt-avatar"><CharacterAvatar :w="w" :id="u.conversation.members[0]||''" :group="u.conversation.group"/></span><div><strong>{{u.conversation.title}}</strong><small>{{u.conversation.group?`${members.length}位成员 · ${groupRole('player')}`:'私聊'}}</small></div><button type="button" @click="u.conversation.group?groupInfo():profile(u.conversation.members[0])">{{u.conversation.group?'群资料':'好友资料'}} ›</button></div>
   <input v-if="searchMessages" v-model="chatSearch" aria-label="搜索聊天记录" placeholder="搜索本群聊天记录">
   <p v-if="u.conversation.announcement" class="pt-announcement">群公告：{{u.conversation.announcement}}</p>
   <div class="pt-pagination" v-if="searchedMessages.length>20"><button type="button" :disabled="(u.historyPage+1)*20>=searchedMessages.length" @click="u.historyPage++">更早记录</button><small>第 {{u.historyPage+1}} 页 · 共 {{searchedMessages.length}} 条</small><button type="button" :disabled="u.historyPage===0" @click="u.historyPage--">较新记录</button></div>
   <div ref="feed" class="pt-chat-feed" role="log" aria-label="终端聊天消息"><p v-if="!u.messages.length" class="pt-empty">从一句问候开始。</p><article v-for="m in pagedMessages" :key="m.id" class="pt-message" :class="{mine:m.sender==='player'}"><span class="pt-avatar"><img v-if="m.sender==='player'&&u.t.avatar" :src="u.t.avatar" :style="u.avatarStyle" alt="我的头像"><CharacterAvatar v-else :w="w" :id="m.sender"/></span><div><small>{{m.displayName||u.name(m.sender)}}</small><p>{{m.text}}</p><time>{{m.source?'剧情记录':messageTime(m.at)}}</time></div></article></div>
   <button v-if="u.messages.at(-1)?.sender==='player'" type="button" class="pt-link" :disabled="u.working" @click="u.sendChat(true)">重试角色回复</button>
   <form class="pt-composer" @submit.prevent="u.sendChat()"><AutoTextarea v-model="u.draft" aria-label="终端消息" placeholder="输入消息…" maxlength="2000" rows="1"/><button type="submit" class="pt-primary" :disabled="u.working||!u.draft.trim()">发送</button></form><small class="pt-composer-hint">发送将调用终端 API</small>
  </template>
  <template v-else-if="u.page==='friends'">
   <div class="pt-toolbar"><h2>好友 · {{u.friends.length}}</h2><button type="button" @click="u.go('add')">＋ 添加好友</button></div><button type="button" @click="showImageCharacters=!showImageCharacters">主要角色头像管理</button><section v-if="showImageCharacters"><p>选择角色编辑头像。</p><button v-for="a in majorCharacters" :key="a.id" type="button" class="pt-row" @click="imageCharacter=a.id"><span class="pt-avatar"><CharacterAvatar :w="w" :id="a.id"/></span>{{a.name}} · 编辑头像</button><p v-if="!majorCharacters.length">角色资料尚未加载，请稍后重试。</p></section><input v-model="u.search" aria-label="搜索好友" placeholder="搜索好友或备注">
   <h3 v-if="u.incoming.length">好友申请 · {{u.incoming.length}}</h3><article v-for="f in u.incoming" :key="'request:'+f.id" class="pt-card pt-friend-request"><span class="pt-avatar"><CharacterAvatar :w="w" :id="f.id"/></span><div><strong>{{u.name(f.id)}}申请添加你</strong><p>{{f.requestReason||f.reply}}</p><small v-if="f.source">号码来源：{{f.source}}</small><small>{{messageTime(f.at||'')}}</small><div class="pt-actions"><button type="button" class="pt-gold" :disabled="u.working" @click="u.answerRequest(f.id,true)">接受</button><button type="button" :disabled="u.working" @click="u.answerRequest(f.id,false)">拒绝</button></div></div></article>
   <p v-if="!u.friends.length" class="pt-empty">好友列表还是空的<br>发送申请后，由角色决定是否接受。</p>
   <button v-for="f in filteredFriends" :key="f.id" type="button" class="pt-row" @click="profile(f.id)"><span class="pt-avatar"><CharacterAvatar :w="w" :id="f.id"/></span><div><strong>{{u.name(f.id)}}</strong><small>{{f.note||'已是好友'}}</small></div><span>›</span></button>
   <h3 v-if="u.activeFriends.some(f=>f.status!=='accepted'&&!(f.direction==='incoming'&&f.status==='pending'))">申请记录</h3><article v-for="f in u.activeFriends.filter(f=>f.status!=='accepted'&&!(f.direction==='incoming'&&f.status==='pending'))" :key="f.id" class="pt-card"><strong>{{u.name(f.id)}} · {{f.status==='pending'?'等待回应':'未接受'}}</strong><p>{{f.reply}}</p><button v-if="f.direction!=='incoming'&&f.code" type="button" :disabled="u.working" @click="u.friendApply(f.id)">{{f.status==='pending'?'重新获取回应':'再次申请'}}</button></article>
  </template>
  <template v-else-if="u.page==='add'">
   <h2>添加好友</h2><form class="pt-code-search" @submit.prevent="u.lookupCode"><input v-model="u.search" aria-label="终端码" placeholder="输入完整的11位终端码" inputmode="numeric" maxlength="11"><button type="submit" :disabled="u.working">查找</button></form>
   <article v-if="u.lookup" class="pt-card"><div class="pt-chat-identity"><span class="pt-avatar"><TerminalIcon name="user"/></span><div><strong>{{u.lookup.name}}</strong><small>{{u.lookup.identity}}</small><small>{{u.lookup.code}}</small></div></div><label>申请留言<textarea v-model="u.note" aria-label="好友申请留言" maxlength="1000" placeholder="介绍自己，并写下申请理由…" rows="4"/></label><button type="button" class="pt-gold" :disabled="u.working||!u.note.trim()||u.friends.some(f=>f.id===u.lookup!.id)" @click="u.friendApply(u.lookup.id)">{{u.friends.some(f=>f.id===u.lookup!.id)?'已是好友':'发送申请'}}</button><p v-if="u.t.friends.find(f=>f.id===u.lookup!.id)?.reply">{{u.t.friends.find(f=>f.id===u.lookup!.id)?.reply}}</p></article>
   <h3 v-if="u.t.friends.some(f=>f.direction!=='incoming')">申请记录</h3><article v-for="f in u.t.friends.filter(f=>f.direction!=='incoming')" :key="f.id" class="pt-card"><strong>{{u.name(f.id)}}</strong><p>{{f.status==='pending'?'申请已发送 · 等待回应':f.status==='accepted'?'申请已通过':'对方暂未接受'}}</p><small>{{f.reply}}</small></article>
  </template>
  <template v-else-if="u.page==='profile'">
   <div class="pt-profile"><h2>{{u.name(u.friendId)}}</h2><span class="pt-avatar large"><CharacterAvatar :w="w" :id="u.friendId"/></span><span>已是好友</span></div><p>{{u.actors.find(a=>a.id===u.friendId)?.identity||'暂无已知身份资料'}}</p><p>{{u.actors.find(a=>a.id===u.friendId)?.relationship||'关系以当前剧情为准'}}</p><p class="pt-card" v-if="u.t.friends.find(f=>f.id===u.friendId)?.reply">{{u.t.friends.find(f=>f.id===u.friendId)?.reply}}</p><CharacterImageEditor :key="u.friendId" :w="w" :id="u.friendId"/><label>备注（仅自己可见）<input v-model="u.note" maxlength="1000"></label><button type="button" :disabled="u.working" @click="u.updateNote">保存备注</button><div class="pt-actions"><button type="button" class="pt-primary" :disabled="u.working" @click="u.openChat(u.friendId)">发送消息</button><button type="button" @click="u.picked=[u.friendId];u.title='';u.go('new-group')">邀请群聊</button><button type="button" class="pt-gold" @click="u.picked=[u.friendId];u.title='';u.go('new-room')">邀请游戏</button></div><button class="pt-link" type="button" :disabled="u.working" @click="u.removeFriend">移除好友（保留聊天记录）</button>
  </template>
  <template v-else-if="['new-group','invite-group','new-room','invite-room'].includes(u.page)">
   <h2>{{titles[u.page]}}</h2><label v-if="!['invite-group','invite-room'].includes(u.page)">{{u.page==='new-room'?'房间名称':'群名称'}}<input v-model="u.title" maxlength="60" placeholder="填写名称"></label><input v-model="u.search" aria-label="选择好友" placeholder="搜索已添加好友"><small>仅显示已添加的好友</small>
   <label v-for="f in filteredFriends.filter(f=>u.page==='invite-room'?!u.room?.members.includes(f.id):u.page!=='invite-group'||!u.conversation?.members.includes(f.id))" :key="f.id" class="pt-row"><span class="pt-avatar"><CharacterAvatar :w="w" :id="f.id"/></span><strong>{{u.name(f.id)}}</strong><input type="checkbox" :checked="u.picked.includes(f.id)" @change="u.toggle(f.id)"></label>
   <h3 v-if="u.incoming.length">好友申请 · {{u.incoming.length}}</h3><article v-for="f in u.incoming" :key="'request:'+f.id" class="pt-card pt-friend-request"><span class="pt-avatar"><TerminalIcon name="user"/></span><div><strong>{{u.name(f.id)}}</strong><p>{{f.requestReason||f.reply}}</p><small>{{messageTime(f.at||'')}}</small><div class="pt-actions"><button type="button" class="pt-gold" :disabled="u.working" @click="u.answerRequest(f.id,true)">接受</button><button type="button" :disabled="u.working" @click="u.answerRequest(f.id,false)">拒绝</button></div></div></article>
   <p v-if="!u.friends.length" class="pt-empty">先添加好友，再邀请他们。</p>
   <template v-if="u.page==='new-room'"><label>游戏风格<select v-model="u.style"><option>日常</option><option>搞笑</option><option>关系互动</option></select></label></template>
   <p>已选择 {{u.picked.length}} 位好友</p><button type="button" class="pt-primary" :disabled="u.working||!u.picked.length" @click="u.page==='invite-room'?u.addRoomFriends():u.page==='new-room'?u.createRoom():u.page==='invite-group'?u.inviteGroup():u.makeGroup()">{{u.page==='invite-room'?'邀请参加游戏':u.page==='new-room'?'发送游戏邀请':u.page==='invite-group'?'邀请入群':'创建群聊'}}</button>
  </template>
  <template v-else-if="u.page==='group-info'&&u.conversation">
   <h2>{{u.conversation.title}}</h2><p class="pt-announcement">群主：{{groupOwner(u.conversation)?u.name(groupOwner(u.conversation)):'待剧情确认'}} · 你是{{groupRole('player')}}</p>
   <button v-if="u.conversation.origin==='story'" type="button" :disabled="u.working" @click="u.refreshGroup">{{u.conversation.managementReady?'根据剧情重新核对群资料':'AI 读取剧情并确定群资料'}}</button>
   <h3>群成员 · {{members.length}}</h3><div class="pt-members"><button v-for="id in members" :data-member-id="id" :data-role="groupRole(id)" :key="id" type="button" @click="member(id)"><span class="pt-avatar"><img v-if="id==='player'&&u.t.avatar" :src="u.t.avatar" :style="u.avatarStyle" alt="我的头像"><CharacterAvatar v-else :w="w" :id="id"/></span>{{u.name(id)}}<small>{{groupRole(id)}}</small></button><button v-if="u.canManage" type="button" @click="u.picked=[];u.go('invite-group')">＋ 邀请</button></div>
   <template v-if="u.canManage"><h3>成员管理</h3><div v-for="id in u.conversation.members.filter(id=>id!==groupOwner(u.conversation!)&&(u.isOwner||!u.conversation?.adminIds?.includes(id)))" :key="'remove:'+id" class="pt-row"><strong>{{u.name(id)}}</strong><button type="button" :disabled="u.working" @click="u.removeMember(id)">移出群聊</button></div></template>
   <template v-if="u.isOwner"><h3>设置群管理员</h3><label v-for="id in members.filter(id=>id!==groupOwner(u.conversation!))" :key="id" class="pt-row"><strong>{{u.name(id)}}</strong><input type="checkbox" :aria-label="'设置'+u.name(id)+'为管理员'" :checked="u.conversation.adminIds?.includes(id)||false" :disabled="u.working" @change="u.setAdmin(id,($event.target as HTMLInputElement).checked)"></label></template>
   <label>群名称<input v-model="u.title" maxlength="60" :readonly="!u.canManage"></label><label>群公告<textarea v-model="u.note" rows="3" maxlength="1000" :readonly="!u.canManage"/></label><button v-if="u.canManage" type="button" class="pt-primary" :disabled="u.working" @click="u.editGroup">保存群资料</button>
   <button type="button" @click="searchMessages=true;chatSearch='';u.go('chat')">查找聊天记录</button><button type="button" class="pt-gold" @click="u.picked=u.conversation.members.filter(id=>u.friends.some(f=>f.id===id));u.title=u.conversation.title;u.go('new-room')">发起国王游戏（仅邀请好友）</button><button v-if="!u.isOwner" type="button" class="pt-link" :disabled="u.working" @click="u.leaveGroup">退出此群聊</button>
  </template>
  <template v-else-if="u.page==='courses'">
   <div class="pt-toolbar"><h2>{{/教官|教师|教授/.test(w.active?.persona.identity||'')?'授课安排':'我的课程'}}</h2><button type="button" :disabled="u.working" @click="u.schedule">更新安排</button></div><div class="pt-tabs"><button type="button" :class="{active:!u.week}" @click="u.week=false">今日</button><button type="button" :class="{active:u.week}" @click="u.week=true">本周</button></div><p>{{u.storyClock.label}}</p><small v-if="!u.week&&!u.storyClock.day">剧情未明确星期，暂列出已知安排。</small><div v-if="u.week&&u.t.courses.length" class="pt-week-wrap"><div class="pt-week-grid"><section v-for="(day,index) in weekNames" :key="day"><strong>{{day}}</strong><button v-for="c in u.t.courses.filter(c=>c.day===index+1)" :key="c.id" type="button" @click="u.courseId=c.id;u.go('course')"><small>{{c.time}}</small>{{c.title}}</button></section></div></div><p v-if="!shownCourses.length" class="pt-empty">暂无明确的课程安排<br>没有明确安排时，可根据你的身份生成。</p><button v-for="c in shownCourses" :key="c.id" type="button" class="pt-course pt-card" @click="u.courseId=c.id;u.go('course')"><span>{{weekNames[c.day-1]}}<b>{{c.time}}</b></span><div><strong>{{c.title}}</strong><p>{{c.place||'地点待明确'}}</p></div><span>›</span></button><small v-if="u.t.scheduleDate">上次读取：{{u.t.scheduleDate}}</small>
  </template>
  <template v-else-if="u.page==='course'&&u.course"><small>{{weekNames[u.course.day-1]}}</small><h2>{{u.course.title}}</h2><h3>{{u.course.time}}—{{u.course.end}}</h3><article class="pt-card"><p>授课角色：{{u.course.teacherId?u.name(u.course.teacherId):'待明确'}}</p><p>地点：{{u.course.place||'待明确'}}</p><p>课前准备：{{u.course.preparation||'暂无已知要求'}}</p></article><button v-if="u.course.teacherId" type="button" class="pt-primary" :disabled="u.working" @click="u.friends.some(f=>f.id===u.course!.teacherId)?u.openChat(u.course.teacherId):u.go('add')">{{u.friends.some(f=>f.id===u.course!.teacherId)?'联系授课角色':'添加授课角色好友'}}</button><button type="button" @click="u.go('messages')">查看已有群聊</button></template>
  <template v-else-if="u.page==='games'"><div class="pt-game-hero"><TerminalIcon name="crown"/><h2>国王游戏</h2><p>抽签出令，与好友一起玩。</p></div><button type="button" class="pt-gold" @click="startRoom">创建房间 ›</button><h3>进行中的房间</h3><button v-for="r in u.t.rooms" :key="r.id" type="button" class="pt-row" @click="u.roomId=r.id;u.go('room')"><TerminalIcon name="crown"/><div><strong>{{r.name}}</strong><small>{{r.rounds.length}}轮记录 · {{r.members.length}}位受邀成员</small></div><span>›</span></button></template>
  <template v-else-if="u.page==='room'&&u.room"><div class="pt-game-hero"><TerminalIcon name="crown"/><h2>{{u.room.name}}</h2><p>{{u.room.style}} · 好友专属</p></div><article v-for="id in u.room.members" :key="id" class="pt-row"><span class="pt-avatar"><TerminalIcon name="user"/></span><strong>{{u.name(id)}}</strong><small>{{id==='player'?'房主 · 已就绪':{accepted:'已接受',declined:'未参加',pending:'等待回应'}[u.room.invitations[id]]}}</small></article><button type="button" :disabled="u.working||!!(u.round&&u.round.phase!=='complete')" @click="u.picked=[];u.go('invite-room')">邀请其他好友</button><p>已确认 {{1+Object.values(u.room.invitations).filter(s=>s==='accepted').length}} 人</p><button v-if="Object.values(u.room.invitations).some(s=>s!=='accepted')" type="button" :disabled="u.working" @click="u.retryInvite">重新邀请未加入的好友</button><button v-if="u.round&&u.round.phase!=='complete'" type="button" class="pt-gold" @click="u.go('king')">继续当前轮</button><button v-else type="button" class="pt-gold" :disabled="u.working||Object.values(u.room.invitations).filter(s=>s==='accepted').length<2" @click="u.startRound">抽签开始{{u.room.rounds.length?'下一轮':'游戏'}}</button><button v-if="u.room.rounds.length" type="button" @click="u.go('history')">游戏记录</button></template>
  <template v-else-if="u.page==='king'&&u.round">
   <p class="pt-round">第 {{String(u.round.number).padStart(2,'0')}} 轮</p><div class="pt-king"><TerminalIcon name="crown"/><h2>本轮国王：{{u.name(u.round.king)}}</h2></div>
   <template v-if="u.round.phase==='command'"><div class="pt-hidden-cards"><span v-for="n in Object.keys(u.round.numbers).length" :key="n">？<small>秘密编号</small></span></div><small v-if="u.round.king!=='player'">你的编号：{{u.round.numbers.player}}</small><small v-else>你是国王，不持有编号。目标将在出令后揭晓。</small><template v-if="u.round.king==='player'"><label>输入你的命令<textarea v-model="u.draft" aria-label="国王命令" maxlength="1000" placeholder="写下本轮命令…" rows="4"/></label><p>选择目标编号</p><div class="pt-chips"><button v-for="n in Object.keys(u.round.numbers).length" :key="n" type="button" :class="{active:u.targets.includes(n)}" @click="u.targets=u.targets.includes(n)?u.targets.filter(i=>i!==n):[...u.targets,n]">{{n}}号</button></div><p>备选指令（选择后可编辑）</p><div class="pt-chips"><button v-for="text in ['分享一件今天开心的事。','夸奖一位参与者。','模仿一个有趣的表情。']" :key="text" type="button" @click="u.draft=text">{{text}}</button></div></template><button type="button" class="pt-gold" :disabled="u.working" @click="u.command">{{u.round.king==='player'?'发布命令':'请国王出令'}}</button></template>
   <template v-else><article class="pt-command"><small>国王命令</small><p>{{u.round.command}}</p></article><div class="pt-reveal"><article v-for="id in targetActors(u.round)" :key="id"><b>{{u.round.numbers[id]}}号</b><span class="pt-avatar"><TerminalIcon name="user"/></span><strong>{{u.name(id)}}</strong></article></div><article v-for="r in u.round.replies" :key="r.id" class="pt-card"><strong>{{u.name(r.id)}}</strong><p>{{r.text}}</p><div v-if="r.refused" class="pt-penalty"><small>接受游戏惩罚</small><p>{{r.penalty}}</p></div></article><button v-if="npcWaiting" type="button" class="pt-gold" :disabled="u.working" @click="u.retryReact">获取角色回应</button><section class="pt-game-interactions"><article v-for="i in u.round.interactions||[]" :key="i.id" class="pt-card"><strong>{{w.active?.persona.name||'我'}} · {{ {chat:'发言',complete:'完成命令',refuse:'拒绝并承担惩罚'}[i.kind] }}</strong><p>{{i.text}}</p><article v-for="reply in i.replies" :key="reply.id"><strong>{{u.name(reply.id)}}</strong><p>{{reply.text}}</p><p v-if="reply.refused">游戏惩罚：{{reply.penalty}}</p></article><button v-if="i.status==='pending'" type="button" :disabled="u.working" @click="u.retryGameInteract">重试角色后续回应</button></article></section><form @submit.prevent="u.gameInteract"><h3>游戏互动</h3><AutoTextarea v-model="u.draft" aria-label="游戏互动" placeholder="写下你的台词或动作；普通发言不会推进轮次。" maxlength="2000"/><div class="pt-actions"><button type="submit" class="pt-primary" :disabled="u.working||u.round.interactions?.some(i=>i.status==='pending')">发送互动</button><button v-if="mineWaiting" type="button" :disabled="u.working||u.round.interactions?.some(i=>i.status==='pending')" @click="u.playerReply(false)">完成命令并回应</button><button v-if="mineWaiting" type="button" :disabled="u.working||u.round.interactions?.some(i=>i.status==='pending')" @click="u.playerReply(true)">拒绝并接受惩罚</button></div></form><template v-if="u.round.phase==='complete'"><div class="pt-complete">✓ 本轮结束</div><button type="button" class="pt-gold" :disabled="u.working||u.round.interactions?.some(i=>i.status==='pending')" @click="u.startRound">下一轮</button><button type="button" @click="u.go('games')">保存并退出游戏</button></template></template><button type="button" class="pt-link" @click="u.go('history')">查看游戏记录</button>
  </template>
  <template v-else-if="u.page==='history'&&u.room"><h2>{{u.room.name}}</h2><details v-for="r in [...u.gameHistory].reverse()" :key="r.number" class="pt-card"><summary>第{{r.number}}轮 · {{u.name(r.king)}} · {{r.phase==='complete'?'已结束':'进行中'}}</summary><p>{{r.command||'尚未出令'}}</p><article v-for="i in r.interactions||[]" :key="i.id"><strong>{{w.active?.persona.name||'我'}}</strong><p>{{i.text}}</p><article v-for="reply in i.replies" :key="reply.id"><strong>{{u.name(reply.id)}}</strong><p>{{reply.text}}</p><p v-if="reply.refused">游戏惩罚：{{reply.penalty}}</p></article><small v-if="i.status==='pending'">角色后续回应待重试</small></article><article v-for="reply in r.replies" :key="reply.id"><strong>{{u.name(reply.id)}}</strong><p>{{reply.text}}</p><p v-if="reply.refused">游戏惩罚：{{reply.penalty}}</p></article></details></template>
  <template v-else-if="u.page==='account'"><div class="pt-profile pt-my-profile"><span class="pt-avatar profile-avatar"><img v-if="u.t.avatar" :src="u.t.avatar" :style="u.avatarStyle" alt="我的头像"><TerminalIcon v-else name="user"/></span><h2>{{w.active?.persona.name||'我的终端'}}</h2><small>终端码：{{u.ownCode||'剧情尚未提供'}}</small><p>{{u.t.bio||'这个家伙很懒，还没有写个人简介喵~'}}</p></div><label class="pt-upload">更换头像<input type="file" accept="image/png,image/jpeg,image/webp" :disabled="u.working" @change="avatarChange"></label><template v-if="u.t.avatar"><label>头像缩放<input type="range" min="1" max="2.5" step="0.05" :value="u.t.avatarView?.scale||1" @change="u.adjustAvatar('scale',Number(($event.target as HTMLInputElement).value))"></label><label>水平位置<input type="range" min="-30" max="30" :value="u.t.avatarView?.x||0" @change="u.adjustAvatar('x',Number(($event.target as HTMLInputElement).value))"></label><label>垂直位置<input type="range" min="-30" max="30" :value="u.t.avatarView?.y||0" @change="u.adjustAvatar('y',Number(($event.target as HTMLInputElement).value))"></label></template><label>一句话简介<input v-model="u.bioDraft" aria-label="个人简介" maxlength="160" placeholder="这个家伙很懒，还没有写个人简介喵~"></label><button type="button" class="pt-primary" :disabled="u.working" @click="u.saveBio">保存资料</button><button v-if="u.t.avatar" type="button" :disabled="u.working" @click="u.run(()=>u.commit(t=>{t.avatar='';t.avatarView=undefined}))">恢复默认头像</button><p class="pt-muted">终端 API：{{u.terminalProfile?.name||'未配置'}}</p><button type="button" @click="w.panel='settings';$emit('close')">终端 API 设置 ›</button><button type="button" :disabled="u.working" @click="u.retryAutomatic">自动通讯同步说明</button></template>

 </main>
 <nav class="pt-dock" aria-label="终端导航"><button v-for="item in [{id:'home',icon:'home',name:'桌面'},{id:'messages',icon:'chat',name:'通讯'},{id:'friends',icon:'friends',name:'好友'},{id:'account',icon:'user',name:'我的'}]" :key="item.id" type="button" :class="{active:nav===item.id}" :aria-current="nav===item.id?'page':undefined" @click="u.go(item.id)"><TerminalIcon :name="item.icon"/><span>{{item.name}}<em v-if="item.id==='friends'&&u.incoming.length"> {{u.incoming.length}}</em></span></button></nav><div class="pt-home-indicator" aria-hidden="true"></div>
</section>
</template>
<style>#academy-workspace .pt{--pt-blue:#9bd6ef;--pt-gold:#e3c986;--pt-muted:#9baec1;color:#edf1f3;background:radial-gradient(ellipse at 100% 0,#1a3852 0,transparent 42%),linear-gradient(155deg,#0c1929,#08121f 60%,#101c2a);height:100%;display:flex;flex-direction:column;border:1px solid #718392;border-radius:26px;box-shadow:inset 0 0 0 5px #202934,inset 0 0 0 6px #475767;padding:7px;font:14px/1.7 'Noto Sans SC','Microsoft YaHei',sans-serif;color-scheme:dark;isolation:isolate}#academy-workspace .pt *{box-sizing:border-box}#academy-workspace .pt svg{width:24px;height:24px;flex-shrink:0}#academy-workspace .pt button{font:inherit!important;cursor:pointer;color:inherit!important;border:1px solid #57738a!important;border-radius:9px!important;background:linear-gradient(140deg,#1d344b99,#0d1b2c)!important;padding:9px 13px!important;min-height:38px;box-shadow:none!important;letter-spacing:0!important}#academy-workspace .pt button:hover{border-color:var(--pt-blue)!important;background:#203a50!important}#academy-workspace .pt button:disabled{opacity:.45;cursor:default}#academy-workspace .pt button:focus-visible,#academy-workspace .pt input:focus-visible,#academy-workspace .pt textarea:focus-visible,#academy-workspace .pt select:focus-visible{outline:2px solid var(--pt-blue);outline-offset:2px}#academy-workspace .pt p{margin:8px 0;overflow-wrap:anywhere;white-space:pre-wrap}#academy-workspace .pt h2{font-family:Georgia,'Noto Serif SC',serif;font-size:24px;font-weight:500;line-height:1.45;margin:12px 0 18px}#academy-workspace .pt h3{font-size:15px;margin:20px 0 10px}#academy-workspace .pt small{font-size:12px;color:var(--pt-muted)}#academy-workspace .pt em{font-style:normal;border-radius:20px;background:#b84852;color:#fff;font-size:11px;padding:1px 7px}#academy-workspace .pt label{display:block;color:#c4d4e0;font-size:13px;margin:12px 0}#academy-workspace .pt input:not([type=checkbox]),#academy-workspace .pt textarea,#academy-workspace .pt select{display:block;width:100%;font:inh